import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"プラグイン","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/plugins.md","filePath":"ja-JP/user-guide/settings/plugins.md","lastUpdated":1785214938000}'),n={name:"ja-JP/user-guide/settings/plugins.md"};function o(i,t,p,d,g,l){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="プラグイン" tabindex="-1">プラグイン <a class="header-anchor" href="#プラグイン" aria-label="Permalink to &quot;プラグイン&quot;">​</a></h1><p>インストール済みのすべてのプラグインを一覧表示し、現在読み込まれているプラグイン SDK のバージョンをページヘッダーにバッジとして表示します(<a href="./../../dev-guide/">開発者ガイド</a>と照らし合わせてプラグインを開発している場合に役立ちます)。</p><h2 id="プラグインごとのカード" tabindex="-1">プラグインごとのカード <a class="header-anchor" href="#プラグインごとのカード" aria-label="Permalink to &quot;プラグインごとのカード&quot;">​</a></h2><p>インストールされたプラグインごとに、アイコン、名前、バージョン、DLL ファイル名、<strong>全体的な機能の説明</strong> を示すカードが表示されます。</p><p>カードをクリックすると展開し、種類(検索プロバイダー、動的メニュープロバイダーなど)ごとにグループ化された登録済みコンポーネントが表示されます。切り替え可能な各コンポーネントには専用の <strong>有効/無効チェックボックス</strong> があります。必須とマークされたコンポーネントは代わりに鍵アイコンが表示され、オフにできません。コンポーネントにカーソルを合わせると <strong>詳細な機能のツールチップ</strong> が表示されます。</p><p>グループ(またはプラグイン全体)に切り替え可能なコンポーネントが2つ以上ある場合、そのヘッダーの横に <strong>すべて選択/すべて選択解除</strong> リンクが表示され、そのスコープ内のすべてのチェックボックスを1つずつではなく一括で切り替えられます。</p><p>プラグインが独自の設定(単純な有効/無効を超えたカスタム設定)を公開している場合、カードのヘッダーに <strong>設定</strong> ボタンが表示され、そのプラグイン独自の設定ダイアログが開きます。</p><p>ページ下部のバナーは、一部のコンポーネントの切り替えが SwiftList の再起動後にのみ反映されることを知らせます。</p><p>プラグインが1つもインストールされていない場合、代わりに空の状態メッセージが表示されます。</p><p>プラグイン独自の <strong>設定</strong> ダイアログが実際にどのようなものかの具体例(トリガーキーワードの変更など)については、<a href="./../instant-answers.html">インスタントアンサーとキーワードショートカット</a>を参照してください。</p>',10)])])}const c=e(n,[["render",o]]);export{u as __pageData,c as default};
